    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002af', 'equals and hashCode are generated from the components', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002af', 'A compact constructor can validate and normalise before assignment', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002af', 'Its components are final, so the record is shallowly immutable', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002af', 'A record can extend another class to share fields', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b0', 'You cannot write new T[] or test instanceof List<String> at runtime', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b0', 'Generic code is slower because every call is reflective', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b0', 'A List<String> and a List<Integer> are different classes at runtime', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b0', 'Generic types cannot be used as map keys', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b1', 'List<? extends Number>, because the list produces values you read', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b1', 'List<? super Number>, because the method consumes the list', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b1', 'List<Number>, because wildcards are only for generic classes', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b1', 'List<?>, because the element type does not matter when reading', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b2', 'IOException when reading a file that may not be there', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b2', 'NullPointerException, to keep the program running', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b2', 'ArrayIndexOutOfBoundsException, to guard a loop', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b2', 'OutOfMemoryError, to free some caches and retry', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b3', 'filter and map do nothing until a terminal operation runs', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b3', 'A stream can only be consumed once', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b3', 'Elements flow one at a time, so findFirst can stop early', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b3', 'forEach on a parallel stream is a safe way to fill an ArrayList', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b4', 'The total is usually short, because ++ is read-add-write and they interleave', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b4', 'The total is always correct: int writes are atomic in Java', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b4', 'The JVM throws ConcurrentModificationException', 0, 3
