    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b8', 'A static Map that entries are added to and never removed from', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b8', 'A listener registered on a long-lived object and never unregistered', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b8', 'A ThreadLocal set on a pooled thread and never cleared', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b8', 'A local variable going out of scope at the end of a method', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b9', 'A non-static inner class holds a hidden reference to its enclosing instance', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b9', 'Static nested classes are allocated on the stack instead of the heap', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b9', 'Only static nested classes can be private', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002b9', 'Non-static inner classes cannot be garbage collected at all', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002ba', 'The JIT compiles the hot path after the first rounds have run interpreted', 1, 1
