    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bb', 'Mark the list final so the JIT can inline the lookup', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-0000000002bc', 'The domain classes import no framework and need no container to test', 1, 1
